mapper.select:
select max(cur_time) as mxTime
from stock_rt_info
where stock_code = #{stockCode}
  and cur_time between #{startDate} and #{endDate}
group by date_format(cur_time, '%Y%m%d')

SELECT stock_code AS stockCode,
       cur_time   AS mxTime,
       cur_price  AS closePrice
FROM stock_rt_info
WHERE stock_code = #{code}
  AND cur_time BETWEEN #{startDate} AND #{endDate}
  AND cur_time IN (
    SELECT MAX(cur_time)
    FROM stock_rt_info
    WHERE stock_code = #{code}
      AND cur_time BETWEEN #{startDate} AND #{endDate}
    GROUP BY YEARWEEK(cur_time)
)
